import { generateKeyPairSync } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { buildManifest, signManifest, canonicalJSON } from '../src/bundle/signature.mjs';
import { GENESIS } from '../src/publish/checkpoint.mjs';

// Ephemeral keys only: no real credential is ever generated by the tests.
export function makeKey(keyId, { notBefore = '2026-01-01T00:00:00Z', notAfter = '2030-12-31T00:00:00Z', revokedAt } = {}) {
  const { privateKey, publicKey } = generateKeyPairSync('ed25519');
  return {
    privateKey,
    pem: privateKey.export({ type: 'pkcs8', format: 'pem' }),
    entry: { keyId, publicKeyPem: publicKey.export({ type: 'spki', format: 'pem' }), notBefore, notAfter, ...(revokedAt ? { revokedAt } : {}) },
  };
}

export const NOW = Date.parse('2026-11-28T09:00:00Z');
export const COMMIT = 'a'.repeat(40);
const FIXTURE = readFileSync(new URL('./fixtures/valid-content.json', import.meta.url), 'utf8');
export const validContent = () => JSON.parse(FIXTURE);
export const bytesOf = content => Buffer.from(canonicalJSON(content), 'utf8');

export function signedBundle(content, key, { sequence = 1, basedOn = GENESIS, createdAt = '2026-11-28T08:00:00Z' } = {}) {
  const bundleBytes = bytesOf(content);
  const manifest = buildManifest({ bundleBytes, sequence, basedOn, sourceCommit: COMMIT, createdAt, keyId: key.entry.keyId });
  return { bundleBytes, manifest, signature: signManifest(manifest, key.privateKey) };
}
